1	/**
2	 * Billing term definitions + discount math, shared by ordering, renewal,
3	 * the deploy wizard, invoices and the domain flow. Discounts are the platform's
4	 * promo (longer commitment = cheaper); tune here (or later via admin Settings).
5	 */
6	
7	export type VpsTerm = { months: number; label: string; short: string; discountPct: number };
8	
9	/** The ANNUAL term is 12 months — the one term whose discount is admin-configurable. */
10	export const ANNUAL_TERM_MONTHS = 12;
11	
12	/**
13	 * The annual (12-month) commitment discount SHIPPED as the default, and the fallback
14	 * for the `annual_discount_percent` admin setting (lib/annual-discount.ts).
15	 *
16	 * It MUST equal the 12-month `VPS_TERMS` discountPct below: a platform whose
17	 * `Setting` table has no `annual_discount_percent` row must price the annual term
18	 * EXACTLY as it did before the setting existed, so no existing annual server's
19	 * renewal price moves the moment this wiring lands. The setting only ever raises or
20	 * lowers it deliberately, from the admin Billing panel.
21	 */
22	export const DEFAULT_ANNUAL_DISCOUNT_PCT = 10;
23	
24	export const VPS_TERMS: VpsTerm[] = [
25	  { months: 1, label: "Monthly", short: "1 mo", discountPct: 0 },
26	  // Annual is admin-configurable — this is only the SHIPPED default. Every charge
27	  // path resolves the live rate via `annualDiscountPct()` and passes it through
28	  // `vpsTermPriceCents`; this constant is what an un-wired caller (and a 2-arg call)
29	  // falls back to. Keep it === DEFAULT_ANNUAL_DISCOUNT_PCT.
30	  { months: 12, label: "Annual", short: "1 yr", discountPct: DEFAULT_ANNUAL_DISCOUNT_PCT },
31	  { months: 24, label: "Biennial", short: "2 yr", discountPct: 15 },
32	  { months: 36, label: "Triennial", short: "3 yr", discountPct: 20 },
33	];
34	
35	export function vpsTerm(months: number): VpsTerm {
36	  return VPS_TERMS.find((t) => t.months === months) ?? VPS_TERMS[0];
37	}
38	
39	/**
40	 * The discount percent to apply to a term.
41	 *
42	 * For the ANNUAL (12-month) term this is admin-configurable: pass the
43	 * `annualDiscountPct` resolved from the `annual_discount_percent` setting
44	 * (lib/annual-discount.ts) and it WINS over the shipped default. Every other term
45	 * keeps its fixed `VPS_TERMS` rate. Omitting the override — or passing a
46	 * non-finite value — falls back to the shipped default, so a 2-arg
47	 * `vpsTermPriceCents` call and any caller that has not been wired up price annual at
48	 * `DEFAULT_ANNUAL_DISCOUNT_PCT`, i.e. exactly what the platform shipped before.
49	 * Clamped to 0..90 here as a second line of defence behind the setting reader.
50	 */
51	export function termDiscountPct(months: number, annualDiscountPct?: number): number {
52	  if (months === ANNUAL_TERM_MONTHS && annualDiscountPct != null && Number.isFinite(annualDiscountPct)) {
53	    return Math.min(90, Math.max(0, annualDiscountPct));
54	  }
55	  return vpsTerm(months).discountPct;
56	}
57	
58	/**
59	 * Total charge (cents) for a plan over a term, discount applied.
60	 *
61	 * `annualDiscountPct` (optional) overrides the ANNUAL term's discount with the
62	 * admin-configured rate; see `termDiscountPct`. It is the ONE knob that makes
63	 * annual billing configurable while keeping this the single price formula —
64	 * displayed (deploy wizard), charged (lib/order.ts) and renewed (renewalCharge)
65	 * all call this with the SAME resolved rate, so they cannot disagree.
66	 */
67	export function vpsTermPriceCents(monthlyCents: number, months: number, annualDiscountPct?: number): number {
68	  const pct = termDiscountPct(months, annualDiscountPct);
69	  return Math.round(monthlyCents * months * (1 - pct / 100));
70	}
71	
72	/**
73	 * Effective monthly-equivalent price after the term discount (for "$/mo" display).
74	 *
75	 * `months <= 0` returns the undiscounted monthly price rather than dividing by it.
76	 * This is not display hygiene — it is a money guard. `prorateDeltaCents`
77	 * (lib/proration.ts) prices BOTH halves of every upgrade and downgrade credit
78	 * through this function using `Server.termMonths`, and a 0 there made the division
79	 * `0 / 0` → NaN, which sails through `Math.round`, through `Math.max(0, delta)`
80	 * (NaN is not > 0, so the clamp returns NaN, not 0) and into `debitWallet` as the
81	 * amount to take. The result is a charge that either explodes at the database or,
82	 * on the credit side, writes NaN where a customer's balance used to be. The column
83	 * defaults to 1 and every writer clamps to >= 1 today, so this is a latch, not a
84	 * live bug — but a shared money function must not have a NaN in it.
85	 */
86	export function vpsEffectiveMonthly(monthlyCents: number, months: number, annualDiscountPct?: number): number {
87	  if (!Number.isFinite(months) || months <= 0) return Math.round(monthlyCents);
88	  return Math.round(vpsTermPriceCents(monthlyCents, months, annualDiscountPct) / months);
89	}
90	
91	export type DomainTerm = { years: number; label: string; discountPct: number };
92	
93	export const DOMAIN_TERMS: DomainTerm[] = [
94	  { years: 1, label: "1 year", discountPct: 0 },
95	  { years: 2, label: "2 years", discountPct: 5 },
96	  { years: 3, label: "3 years", discountPct: 10 },
97	];
98	
99	export function domainTerm(years: number): DomainTerm {
100	  return DOMAIN_TERMS.find((t) => t.years === years) ?? DOMAIN_TERMS[0];
101	}
102	
103	/** Total charge (cents) for a domain over N years, discount applied. */
104	export function domainTermPriceCents(perYearCents: number, years: number): number {
105	  const t = domainTerm(years);
106	  return Math.round(perYearCents * years * (1 - t.discountPct / 100));
107	}
108	
109	/** Add whole months to a date (UTC-safe enough for billing windows). */
110	export function addMonths(from: Date, months: number): Date {
111	  const d = new Date(from);
112	  d.setMonth(d.getMonth() + months);
113	  return d;
114	}
115

1	import { vpsTerm, vpsTermPriceCents } from "./billing-terms";
2	import { extraDiskCentsAt } from "./extra-disk";
3	import { type BackupTier, backupTierMonthlyCents } from "./backup-tiers";
4	
5	/**
6	 * What one renewal costs — the SINGLE definition, used by every path that quotes
7	 * or charges one: the automatic sweep in worker/billing.ts, the saved-card path,
8	 * the "Renew now" button, the server page and the deploy wizard's term cards.
9	 *
10	 * WHY IT LIVES IN ITS OWN FILE. It used to sit in lib/stripe-cards.ts, which
11	 * imports the Stripe SDK and (transitively) nodemailer. The moment a CLIENT
12	 * component — the deploy wizard — needed the renewal price, that import chain
13	 * dragged `nodemailer/lib/dkim` into the browser bundle and the build failed with
14	 * "Can't resolve 'fs'". The pricing rule is pure arithmetic and has no business
15	 * carrying a mail transport with it, so it lives here with only the two tiny
16	 * modules it genuinely needs. lib/stripe-cards.ts re-exports it, so no server-side
17	 * caller had to change.
18	 *
19	 * The rule this file exists to enforce: there is ONE renewal formula. Two
20	 * incidents in one day came from a second copy — first a button that hardcoded
21	 * "+30 days" and the monthly price while the action charged a full term ($8.99
22	 * shown, $97.09 taken), then the shared quote written to fix it, which computed
23	 * from `plan.priceCents` and so ignored `gamePlan` and would have billed a $4.99
24	 * game server at its $8.99 base plan. Do not add a second formula.
25	 */
26	export type RenewalCharge = {
27	  months: number;
28	  totalCents: number;
29	  /** The extra-root-disk portion, which gets its own invoice line. */
30	  extraDiskCents: number;
31	  extraDiskMonthlyCents: number;
32	  /** The paid backup-tier portion (Plus retention), which gets its own invoice line. */
33	  backupCents: number;
34	  backupMonthlyCents: number;
35	  /** Human label for the invoice / receipt ("Nebula VPS" or the game plan name). */
36	  label: string;
37	};
38	
39	export type PricedServer = {
40	  termMonths: number;
41	  extraDiskGB: number;
42	  plan: { name: string; priceCents: number };
43	  gamePlan: { name: string; priceCents: number; termMonths: number } | null;
44	  dedicatedIp: unknown | null;
45	  /** Paid backup retention tier. A full Server row supplies it; synthetic callers must pass it. */
46	  backupTier: BackupTier;
47	};
48	
49	/**
50	 * The admin-priced inputs a renewal is charged against. Every field is REQUIRED
51	 * deliberately, mirroring how the codebase guards renewal pricing everywhere else
52	 * (`termPromoPercent` is likewise required in lib/proration.ts): a call site that
53	 * builds this object cannot silently forget one and fall back to a stale default.
54	 */
55	export type RenewalPrices = {
56	  ipMonthlyCents: number;
57	  extraDiskPerGbCents: number;
58	  backupPlusCents: number;
59	  /**
60	   * The admin-configured ANNUAL discount (percent), resolved from the
61	   * `annual_discount_percent` setting via `annualDiscountPct()`.
62	   *
63	   * REQUIRED — not optional. A 12-month server renews at
64	   * `vpsTermPriceCents(price, 12, annualDiscountPct)`; if a call site could OMIT
65	   * this it would silently price annual at the shipped default (10%) while the
66	   * owner had set, say, 20% — the rate the customer was shown and charged at order.
67	   * Required turns that into a compile error at every one of the ~8 places that
68	   * build this object, so the annual setting cannot be forgotten on any renewal
69	   * path and `displayed === charged === renewed` holds.
70	   */
71	  annualDiscountPct: number;
72	};
73	
74	export function renewalCharge(
75	  server: PricedServer,
76	  prices: RenewalPrices,
77	): RenewalCharge {
78	  const isGame = !!server.gamePlan;
79	  const months = isGame ? server.gamePlan!.termMonths : vpsTerm(server.termMonths).months;
80	  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
81	  // are a flat all-in price and never carry the add-on lines.
82	  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
83	  const extraDiskCents = extraDiskMonthlyCents * months;
84	  // Paid backup retention (Plus) rides alongside extra disk: billed every cycle at
85	  // the current admin price, and — like every add-on line — NOT carried by a game
86	  // plan (renewalCharge's game branch is flat all-in, so game servers are never
87	  // sold a paid backup tier; see lib/backup-upgrade.ts's game guard).
88	  const backupMonthlyCents = isGame ? 0 : backupTierMonthlyCents(server.backupTier, prices.backupPlusCents);
89	  const backupCents = backupMonthlyCents * months;
90	  const totalCents = isGame
91	    ? server.gamePlan!.priceCents
92	    : vpsTermPriceCents(server.plan.priceCents, months, prices.annualDiscountPct) +
93	      // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP,
94	      // not off the intent flag — a NAT-fallback server must never be charged for
95	      // an IP it never received.
96	      (server.dedicatedIp ? prices.ipMonthlyCents * months : 0) +
97	      extraDiskCents +
98	      backupCents;
99	  return {
100	    months,
101	    totalCents,
102	    extraDiskCents,
103	    extraDiskMonthlyCents,
104	    backupCents,
105	    backupMonthlyCents,
106	    label: isGame ? server.gamePlan!.name : `${server.plan.name} VPS`,
107	  };
108	}
