1	// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
2	// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
3	// checkout can provision immediately. Plain server module (not "use server").
4	import { z } from "zod";
5	import { Prisma } from "@prisma/client";
6	import type { User } from "@prisma/client";
7	import { db } from "./db";
8	import { debitWallet, InsufficientBalanceError } from "./wallet";
9	import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
10	import { annualDiscountPct } from "./annual-discount";
11	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
12	import { capacityCheck, diskCapacityCheck } from "./capacity";
13	import { invoiceCreateData } from "./invoices";
14	import { maybeRewardReferral } from "./actions-growth";
15	import { currentPromo } from "./promotions";
16	import {
17	  claimFirstMonthFree,
18	  confirmReservation,
19	  firstMonthFreeEnabled,
20	  firstMonthFreeAppliesTo,
21	  setPromoOrderRef,
22	} from "./promo-redemption";
23	import { extraDiskPerGbCents } from "./disk-expand";
24	import {
25	  EXTRA_DISK_MAX_ADD_GB,
26	  EXTRA_DISK_MAX_TOTAL_GB,
27	  effectiveDiskGB,
28	  extraDiskCentsAt,
29	  extraDiskLabel,
30	  normalizeExtraDiskGB,
31	} from "./extra-disk";
32	import { getSettingBool } from "./settings";
33	import { couponOrderDiscountCents } from "./coupon-order";
34	import { confirmOrderCouponReservation, releaseExpiredCouponHoldsFor } from "./coupon-redemption";
35	import { backupPlusMonthlyCents } from "./backup-upgrade";
36	import {
37	  type BackupTier,
38	  backupTierMonthlyCents,
39	  backupTierSpec,
40	  normalizeBackupTier,
41	} from "./backup-tiers";
42	
43	export class OrderError extends Error {}
44	
45	export const orderSchema = z.object({
46	  planId: z.string().min(1),
47	  osTemplateId: z.string().min(1),
48	  hostname: z
49	    .string()
50	    .min(3)
51	    .max(40)
52	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
53	  // Deploy-time extra-disk upsell. Coerced + step-normalized by
54	  // normalizeExtraDiskGB before it reaches here, so this is a range guard only.
55	  extraDiskGB: z.coerce.number().int().min(0).max(EXTRA_DISK_MAX_ADD_GB).optional(),
56	  // Optional checkout promo code. Uppercased + trimmed; the discount + all
57	  // redemption guards live in orderQuote / placeOrder.
58	  couponCode: z.string().trim().max(32).optional(),
59	});
60	
61	export type OrderIntent = {
62	  planId: string;
63	  osTemplateId: string;
64	  hostname: string;
65	  nodeId?: string;
66	  addonMalware?: boolean;
67	  addonBackup?: boolean;
68	  addonDocker?: boolean;
69	  termMonths?: number;
70	  dedicatedIp?: boolean;
71	  sshPublicKey?: string;
72	  sshKeyName?: string;
73	  free?: boolean;
74	  /**
75	   * Extra root-disk GB bought at deploy time, ON TOP of the plan's diskGB. The VM
76	   * is provisioned at plan.diskGB + extraDiskGB (worker/index.ts provision), so no
77	   * post-deploy expansion job is needed. Permanent — never shrinks.
78	   */
79	  extraDiskGB?: number;
80	  /** Checkout promo code (e.g. a "one free month" coupon), uppercased. */
81	  couponCode?: string;
82	  /**
83	   * Paid backup RETENTION tier bought at deploy time. FREE (included) or PLUS
84	   * (keep 7, priced monthly like the other add-ons). Round-tripped through Stripe
85	   * metadata, so it stays a tiny string.
86	   */
87	  backupTier?: BackupTier;
88	};
89	
90	/**
91	 * The price an order was SOLD at: the total, and the promo rate that produced it.
92	 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
93	 *
94	 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
95	 * path quoted a total, charged the CARD its share of that total at Stripe, and
96	 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
97	 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
98	 * and lib/promotions.ts always has an active sale that rotates by calendar date,
99	 * so a rotation between "customer clicked Deploy" and "customer came back from
100	 * Stripe" re-priced the order AFTER the card had cleared and took the difference
101	 * out of the wallet with no new consent. With no balance to take it from, the
102	 * payment was captured and no server was created.
103	 *
104	 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
105	 * Stripe metadata for exactly this reason; the order path was the one that
106	 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
107	 * the customer was shown is not recomputed later, it is carried.
108	 *
109	 * `promoPercent` and `promoName` travel WITH the total because they are not
110	 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
111	 * at (every later proration prices against it), and the promo name is the ledger
112	 * and invoice text the customer reads. Honouring a 30%-off price while stamping
113	 * today's 15% would hand every later proration the wrong basis and print a
114	 * discount on the invoice that does not match the money taken.
115	 */
116	export type OrderPrice = {
117	  /** Total to charge, in cents — the figure the customer consented to. */
118	  chargeCents: number;
119	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
120	  promoPercent: number;
121	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
122	  promoName: string;
123	};
124	
125	/** The sold price implied by a quote — the ONE place a quote becomes a price. */
126	export function orderPriceOf(quote: {
127	  chargeCents: number;
128	  promo: { discountPercent: number; name: string };
129	}): OrderPrice {
130	  return {
131	    chargeCents: quote.chargeCents,
132	    promoPercent: quote.promo.discountPercent,
133	    promoName: quote.promo.name,
134	  };
135	}
136	
137	/**
138	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
139	 * well-formed: a half-parsed price would be worse than no price at all, because
140	 * the caller's fallback (re-quote) is at least internally consistent.
141	 */
142	export function parseOrderPrice(raw: unknown): OrderPrice | null {
143	  let obj: unknown = raw;
144	  if (typeof raw === "string") {
145	    try {
146	      obj = JSON.parse(raw);
147	    } catch {
148	      return null;
149	    }
150	  }
151	  if (!obj || typeof obj !== "object") return null;
152	  const { chargeCents, promoPercent, promoName } = obj as Record<string, unknown>;
153	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
154	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
155	  if (promoPercent < 0 || promoPercent > 100) return null;
156	  return { chargeCents, promoPercent, promoName: typeof promoName === "string" ? promoName : "" };
157	}
158	
159	/** Extract a plain OrderIntent from a deploy form. */
160	export function intentFromFormData(formData: FormData): OrderIntent {
161	  return {
162	    planId: String(formData.get("planId") ?? ""),
163	    osTemplateId: String(formData.get("osTemplateId") ?? ""),
164	    hostname: String(formData.get("hostname") ?? ""),
165	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
166	    addonMalware: formData.get("addon_malware") === "1",
167	    addonBackup: formData.get("addon_backup") === "1",
168	    addonDocker: formData.get("addon_docker") === "1",
169	    termMonths: Number(formData.get("termMonths") ?? 1),
170	    dedicatedIp: formData.get("dedicatedIp") === "1",
171	    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
172	    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
173	    free: formData.get("free") === "1",
174	    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
175	    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
176	    // bought so it drops out of JSON.stringify: the intent is round-tripped
177	    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
178	    // createOrderCheckout), and every byte of headroom matters there.
179	    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
180	    couponCode: String(formData.get("couponCode") ?? "").trim().toUpperCase() || undefined,
181	    // Only PLUS is a paid choice; left UNDEFINED for FREE (the included tier) so it
182	    // drops out of the Stripe-metadata JSON round-trip, like extraDiskGB. orderQuote
183	    // re-normalizes undefined back to FREE.
184	    backupTier: normalizeBackupTier(formData.get("backup_tier")) === "PLUS" ? "PLUS" : undefined,
185	  };
186	}
187	
188	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
189	async function scheduleNode(planRamMB: number) {
190	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
191	  if (nodes.length === 0) return null;
192	  const loads = await Promise.all(
193	    nodes.map(async (n) => {
194	      const agg = await db.server.findMany({
195	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
196	        select: { plan: { select: { ramMB: true } } },
197	      });
198	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
199	      return { node: n, free: n.capacityRamMB - used };
200	    }),
201	  );
202	  loads.sort((a, b) => b.free - a.free);
203	  return loads[0].node;
204	}
205	
206	/** Validate + price an order without placing it. Throws OrderError on any problem. */
207	export async function orderQuote(intent: OrderIntent, opts?: { suppressPromo?: boolean }) {
208	  const parsed = orderSchema.safeParse(intent);
209	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
210	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
211	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
212	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
213	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
214	    throw new OrderError(
215	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
216	    );
217	  }
218	  const term = vpsTerm(Number(intent.termMonths ?? 1));
219	  // The admin-configured ANNUAL discount, resolved ONCE here and passed to
220	  // `vpsTermPriceCents` so the annual term is charged at the same rate the deploy
221	  // wizard displayed and every renewal will bill. Ignored for non-annual terms.
222	  const annualPct = await annualDiscountPct();
223	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
224	
225	  // Extra root disk, priced per GB/month and multiplied over the term exactly
226	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
227	  // promo — the customer pays the same $/GB whichever term they pick, and renews
228	  // at the same rate). Growth is one-way: this is permanent for the server.
229	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
230	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
231	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
232	  const extraDiskCents = extraDiskMonthlyCents * term.months;
233	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
234	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
235	  }
236	
237	  // Paid backup RETENTION tier, priced per month and multiplied over the term
238	  // exactly like the extra-disk add-on (NOT promo-discounted — the customer pays
239	  // the same $/mo whichever term or promo, and renews at the same rate through
240	  // renewalCharge). Only PLUS is paid; FREE (the included tier) is $0.
241	  const backupTier = normalizeBackupTier(intent.backupTier);
242	  const backupMonthlyCents =
243	    backupTier === "FREE" ? 0 : backupTierMonthlyCents(backupTier, await backupPlusMonthlyCents());
244	  const backupCents = backupMonthlyCents * term.months;
245	
246	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
247	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
248	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
249	  // real renewal price and this discounted value is the real first-term price.
250	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
251	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
252	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months, annualPct);
253	  const promo = currentPromo(new Date());
254	  // The promo is now MANAGED: the owner can switch it off, and every claim is
255	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
256	  // quote shows — and placeOrder charges — the full price, so display === charged
257	  // on the disabled path. When it is on, the quote shows the first-month-free
258	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
259	  // the credit is actually granted (a lost race there is charged full).
260	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
261	  // the card path uses it to re-quote for a customer who has already redeemed
262	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
263	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
264	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
265	  // false here and planFirstTermCents falls through to the regular term total.
266	  const promoEnabled =
267	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
268	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
269	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
270	  // YEARS free. So we subtract one month of the plan's rate from the term total.
271	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
272	  // 36-month term the customer pays the term minus one month. Renewals bill the
273	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
274	  const planFirstTermCents =
275	    promoEnabled && promo.firstMonthFree
276	      ? Math.max(0, regularPlanCents - plan.priceCents)
277	      : regularPlanCents;
278	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
279	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
280	  const promoCreditCents = regularPlanCents - planFirstTermCents;
281	
282	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
283	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
284	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
285	  // so the deploy preview can show it; the redemption itself (count + per-user +
286	  // per-IP guards) is claimed atomically in placeOrder.
287	  let couponId: string | null = null;
288	  let couponDiscountCents = 0;
289	  let couponLabel = "";
290	  let couponError = "";
291	  let couponMaxRedemptions: number | null = null;
292	  let couponFirstTimeOnly = false;
293	  const code = (intent.couponCode ?? "").trim().toUpperCase();
294	  if (code) {
295	    if (!(await getSettingBool("coupons_enabled", true))) {
296	      couponError = "Promo codes are currently disabled.";
297	    } else {
298	      const coupon = await db.coupon.findUnique({ where: { code } });
299	      if (!coupon) {
300	        couponError = "That code isn’t valid.";
301	      } else {
302	        const verdict = couponOrderDiscountCents(
303	          {
304	            kind: coupon.kind,
305	            value: coupon.value,
306	            serviceKind: coupon.serviceKind,
307	            planSlug: coupon.planSlug,
308	            maxTermMonths: coupon.maxTermMonths,
309	            active: coupon.active,
310	            expiresAt: coupon.expiresAt,
311	            maxRedemptions: coupon.maxRedemptions,
312	            timesRedeemed: coupon.timesRedeemed,
313	            minAmountCents: coupon.minAmountCents,
314	          },
315	          {
316	            serviceKind: "VPS",
317	            planSlug: plan.slug,
318	            planMonthlyCents: plan.priceCents,
319	            termMonths: term.months,
320	            planChargeCents: planFirstTermCents,
321	          },
322	          new Date(),
323	        );
324	        if (verdict.ok) {
325	          couponId = coupon.id;
326	          couponDiscountCents = verdict.discountCents;
327	          couponLabel = verdict.label;
328	          couponMaxRedemptions = coupon.maxRedemptions;
329	          couponFirstTimeOnly = coupon.firstTimeOnly;
330	        } else {
331	          couponError = verdict.error;
332	        }
333	      }
334	    }
335	  }
336	
337	  const chargeCents = planFirstTermCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
338	  return {
339	    plan,
340	    os,
341	    term,
342	    chargeCents,
343	    // The annual-discount rate this quote was priced at — snapshot onto the Server at
344	    // sale (Finding 2) so every later proration reads the SAME basis and a round trip
345	    // nets to zero even if the admin retunes `annual_discount_percent` in between.
346	    annualPct,
347	    promo,
348	    promoCreditCents,
349	    regularPlanCents,
350	    extraDiskGB,
351	    extraDiskMonthlyCents,
352	    extraDiskCents,
353	    backupTier,
354	    backupMonthlyCents,
355	    backupCents,
356	    couponId,
357	    couponDiscountCents,
358	    couponLabel,
359	    couponError,
360	    couponMaxRedemptions,
361	    couponFirstTimeOnly,
362	  };
363	}
