365	/**
366	 * Place an order: validate, charge the wallet (unless a free admin grant),
367	 * create the Server + PROVISION job. Returns the new server id. Does NOT
368	 * redirect. Callers must ensure funds exist (or pass free) — this still
369	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
370	 *
371	 * `sold` overrides the recomputed price with the one the order was actually SOLD
372	 * at — the card-paid path passes the figure stamped on the Checkout session
373	 * BEFORE the card was charged, so the confirm redirect settles the price the
374	 * customer consented to instead of re-pricing against whatever promo is running
375	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
376	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
377	 * quote, which it computed moments ago in the same request. See OrderPrice.
378	 */
379	/**
380	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
381	 * any failure so nothing partial survives. Kept separate from the order tx so a
382	 * wallet order can surface the failure before any money moves, and a card order
383	 * (already paid) can swallow it without stranding the paid provision.
384	 *
385	 * Guards, all enforced here: first-time-only (no prior paid server), the
386	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
387	 * (the two @@unique constraints on CouponRedemption).
388	 */
389	async function claimOrderCoupon(opts: {
390	  couponId: string;
391	  maxRedemptions: number | null;
392	  firstTimeOnly: boolean;
393	  userId: string;
394	  ipHash: string | null;
395	  amountCents: number;
396	}): Promise<void> {
397	  await db.$transaction(async (tx) => {
398	    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout must
399	    // not stand between them and this coupon on a fresh (wallet) order — and its global
400	    // slot is handed back here too. Guarded to expired RESERVED rows (lib/coupon-redemption.ts).
401	    await releaseExpiredCouponHoldsFor(tx, opts.couponId, opts.userId, opts.ipHash);
402	    if (opts.firstTimeOnly) {
403	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
404	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
405	    }
406	    // Atomic conditional increment — the only thing between the last free slot and
407	    // an over-redemption when two orders race for it.
408	    const claim = await tx.coupon.updateMany({
409	      where:
410	        opts.maxRedemptions === null
411	          ? { id: opts.couponId, active: true }
412	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
413	      data: { timesRedeemed: { increment: 1 } },
414	    });
415	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
416	    try {
417	      await tx.couponRedemption.create({
418	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
419	      });
420	    } catch {
421	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
422	      // this person. Throwing rolls back the increment above with it.
423	      throw new OrderError("You’ve already used this code.");
424	    }
425	  });
426	}
