428	/**
429	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
430	 *
431	 * The card leg discounts `cardCents` up front and only settles the redemption
432	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
433	 * paid provision is never stranded. Without this pre-check, a customer who has
434	 * already used a one-per-person code (or isn't first-time) still gets the
435	 * discounted card charge and the swallow hides it. So before we send them to
436	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
437	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
438	 * (a race could still lose the atomic claim at settle time — that path stays
439	 * swallowed by design), but it closes the everyday bypass.
440	 */
441	export async function orderCouponClaimable(opts: {
442	  couponId: string;
443	  firstTimeOnly: boolean;
444	  maxRedemptions: number | null;
445	  userId: string;
446	  ipHash: string | null;
447	}): Promise<{ ok: true } | { ok: false; error: string }> {
448	  if (opts.firstTimeOnly) {
449	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
450	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
451	  }
452	  const byUser = await db.couponRedemption.findUnique({
453	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
454	  });
455	  if (byUser) return { ok: false, error: "You’ve already used this code." };
456	  if (opts.ipHash) {
457	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
458	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
459	  }
460	  if (opts.maxRedemptions !== null) {
461	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
462	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
463	  }
464	  return { ok: true };
465	}
