467	export async function placeOrder(
468	  user: User,
469	  intent: OrderIntent,
470	  sold?: OrderPrice | null,
471	  opts?: {
472	    ipHash?: string | null;
473	    campaign?: string;
474	    promoReservationToken?: string | null;
475	    couponReservationToken?: string | null;
476	  },
477	): Promise<string> {
478	  const quote = await orderQuote(intent);
479	  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents } = quote;
480	  // Everything below bills off THESE three, never off `quote.chargeCents` /
481	  // `promo` directly: when a sold price is present it is the whole truth about
482	  // what this order costs and what rate it was sold at.
483	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
484	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
485	  const promoName = sold?.promoName || promo.name;
486	  // Note the intro discount on the billing document (first term only; renews full).
487	  const promoNote = promoPercent > 0 ? ` · ${promoName} ${promoPercent}% off first term` : "";
488	
489	  // Managed first-month-free — how this order settles the credit depends on the path:
490	  //   WALLET path (no `sold`): the credit rides on the fresh quote (promoCreditCents
491	  //     > 0), and we contend for it with an atomic INSERT inside the charge tx below.
492	  //   CARD/Stripe path (`sold` present): the credit was already RESERVED before the
493	  //     card was charged, and its hold token travels in `opts.promoReservationToken`.
494	  //     We CONFIRM that hold (never a fresh contended INSERT) — that is what closes
495	  //     the double-claim race. No token => this order was sold at FULL price, so there
496	  //     is nothing to grant. We deliberately do NOT infer the credit from
497	  //     `sold.promoPercent` (currentPromo always stamps 100, even on a full-price VPS
498	  //     order), which would record a redemption for a purchase that never got one.
499	  const walletPromoApplied = !sold && promoCreditCents > 0;
500	  const cardPromoToken = sold ? opts?.promoReservationToken ?? null : null;
501	  // The checkout coupon settles the same two ways:
502	  //   WALLET path (no `sold`): atomic claim in its OWN tx below (claimOrderCoupon), which
503	  //     throws and surfaces before any money moves if the last slot just went.
504	  //   CARD/Stripe path (`sold`): the coupon was RESERVED before the card was charged and
505	  //     its hold token travels in `opts.couponReservationToken`. We CONFIRM that hold
506	  //     inside the charge tx (never a fresh contended claim — that would double-count the
507	  //     global cap and collide on the per-person unique). No token => full-price order.
508	  const cardCouponToken = sold ? opts?.couponReservationToken ?? null : null;
509	
510	  const cap = await capacityCheck(plan.id);
511	  if (!cap.ok) throw new OrderError(cap.reason);
512	
513	  let nodeId: string | null = null;
514	  if (intent.nodeId) {
515	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
516	    if (!n) throw new OrderError("Selected location is not available.");
517	    nodeId = n.id;
518	  } else {
519	    const n = await scheduleNode(plan.ramMB);
520	    nodeId = n?.id ?? null;
521	  }
522	
523	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
524	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
525	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
526	
527	  const addons = {
528	    malwareScanner: !!intent.addonMalware,
529	    dailyBackup: !!intent.addonBackup,
530	    docker: !!intent.addonDocker,
531	  };
532	  const isAdmin = user.role === "ADMIN";
533	  const freeRequested = !!intent.free && isAdmin;
534	  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");
535	
536	  // WALLET path ONLY: claim the coupon atomically BEFORE the order tx, so a wallet order
537	  // fails cleanly (no money moved) if the last slot just went. A free admin grant never
538	  // consumes a customer coupon. The CARD path does NOT claim here — it reserved the coupon
539	  // before checkout and CONFIRMS that hold inside the charge tx below (`cardCouponToken`),
540	  // which is what closes the concurrent-checkout bypass the read-then-swallow left open.
541	  if (!freeRequested && !sold && quote.couponId && quote.couponDiscountCents > 0) {
542	    await claimOrderCoupon({
543	      couponId: quote.couponId,
544	      maxRedemptions: quote.couponMaxRedemptions,
545	      firstTimeOnly: quote.couponFirstTimeOnly,
546	      userId: user.id,
547	      ipHash: opts?.ipHash ?? null,
548	      amountCents: quote.couponDiscountCents,
549	    });
550	  }
551	
552	  const newKey = (intent.sshPublicKey ?? "").trim();
553	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
554	
555	  let server;
556	  try {
557	    server = await db.$transaction(async (tx) => {
558	      // ATOMIC first-month-free claim, INSIDE the charge tx (mirrors claimOrderCoupon).
559	      // Contend for the redemption BEFORE debiting so the debit amount matches the
560	      // outcome. A lost claim never throws — on the wallet path we add the credit
561	      // back and charge FULL; on the card path the money already settled at the sold
562	      // price (screened by the pre-checkout guard in actions.ts), so we keep it and
563	      // record nothing — the same swallow discipline the coupon path uses.
564	      let debitCents = chargeCents;
565	      let promoNoteFinal = promoNote;
566	      let promoClaimId: string | null = null;
567	      let soldFull = false; // wallet order that lost the claim and paid full price
568	      if (!freeRequested && cardPromoToken) {
569	        // CARD/Stripe path: confirm the hold reserved before the card was charged.
570	        // The card already settled at the sold (discounted) price; confirming just
571	        // flips the hold to CONSUMED and anchors it. NEVER a second debit here.
572	        const confirmed = await confirmReservation(tx, cardPromoToken);
573	        if (confirmed) {
574	          promoClaimId = confirmed.id;
575	        } else {
576	          // The hold is gone (released/swept) but the card already paid the discounted
577	          // leg. This is unreachable while the hold outlives the payable session, but
578	          // if it ever happens we must NOT charge more than the customer was shown.
579	          // Try to record the grant so a later renewal can convert it; if even that
580	          // loses (the slot is now another order's), keep the discounted charge and
581	          // log — the same swallow discipline the paid-coupon path uses.
582	          const fallback = await claimFirstMonthFree(tx, {
583	            userId: user.id,
584	            ipHash: opts?.ipHash ?? null,
585	            serviceType: "VPS",
586	            campaign: opts?.campaign ?? "",
587	            chargedCents: chargeCents,
588	          });
589	          if (fallback.claimed) promoClaimId = fallback.id;
590	          else console.error(`[order] first-month-free hold ${cardPromoToken} vanished before confirm for ${user.id}; kept sold price`);
591	        }
592	      } else if (!freeRequested && walletPromoApplied) {
593	        // WALLET path: atomic INSERT inside the charge tx. A lost claim means this
594	        // account/IP already redeemed — add the credit back and charge FULL price.
595	        const claim = await claimFirstMonthFree(tx, {
596	          userId: user.id,
597	          ipHash: opts?.ipHash ?? null,
598	          serviceType: "VPS",
599	          campaign: opts?.campaign ?? "",
600	          chargedCents: chargeCents,
601	        });
602	        if (claim.claimed) {
603	          promoClaimId = claim.id;
604	        } else {
605	          debitCents = chargeCents + promoCreditCents; // full price
606	          promoNoteFinal = "";
607	          soldFull = true;
608	        }
609	      }
610	      // CARD/Stripe path: confirm the coupon hold reserved before the card was charged
611	      // (RESERVED→CONSUMED), inside this tx so the discount's slot commits with the
612	      // provision. NEVER a fresh claim — that would re-increment the cap and collide on
613	      // the per-person unique. `sold` already carries the discounted total the customer
614	      // paid, so no debit changes here.
615	      if (!freeRequested && cardCouponToken) {
616	        const confirmed = await confirmOrderCouponReservation(tx, cardCouponToken);
617	        if (!confirmed) {
618	          // The hold is gone (released/swept) but the card already settled the discounted
619	          // leg. Unreachable while the hold outlives the payable session (its reservedUntil
620	          // is pinned past the Checkout expiry); if it ever happens we keep the discounted
621	          // charge (never overcharge past what was shown) and log — the same swallow
622	          // discipline the paid path uses. We do NOT mint a replacement claim (its cap
623	          // increment could over-redeem).
624	          console.error(`[order] coupon hold ${cardCouponToken} vanished before confirm for paid order ${user.id}; kept sold price`);
625	        }
626	      }
627	      // The rate this term was actually sold at: 0% off when a wallet order lost the
628	      // claim and paid full, otherwise the promo/sold percent (100 admin grant).
629	      const effectivePromoPercent = freeRequested ? 100 : soldFull ? 0 : promoPercent;
630	      if (!freeRequested) {
631	        // For a multi-month term (Annual etc.), spell out the effective monthly-
632	        // equivalent of the PLAN portion on the billing document, derived from the
633	        // very `regularPlanCents` that was charged (its term discount already baked
634	        // in) — never a second computation. So an annual line reads "Annual
635	        // ($8.09/mo)" and the customer can see the yearly commitment AND its real
636	        // per-month rate. Omitted for the 1-month term, where it would just repeat
637	        // the monthly price.
638	        const effMonthlyCents = term.months > 1 ? Math.round(quote.regularPlanCents / term.months) : 0;
639	        const termLabel =
640	          term.months > 1 ? `${term.label} ($${(effMonthlyCents / 100).toFixed(2)}/mo)` : term.label;
641	        await debitWallet(tx, user.id, debitCents);
642	        await tx.walletTransaction.create({
643	          data: {
644	            userId: user.id,
645	            amountCents: -debitCents,
646	            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${termLabel}${promoNoteFinal}`,
647	          },
648	        });
649	        // Billing document for the charge — created inside the same debit tx so it
650	        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
651	        // Extra disk gets its OWN line so the customer can see exactly what the
652	        // permanent storage costs; the lines always sum back to debitCents.
653	        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${termLabel}${promoNoteFinal}`;
654	        // Both add-ons get their OWN line; the base plan line is the remainder, so
655	        // the lines always sum back to debitCents.
656	        const planLineCents = debitCents - extraDiskCents - backupCents;
657	        await tx.invoice.create({
658	          data: invoiceCreateData({
659	            userId: user.id,
660	            description: lineDesc,
661	            status: "PAID",
662	            period: { start: new Date(), end: addMonths(new Date(), term.months) },
663	            lineItems: [
664	              { description: lineDesc, qty: 1, unitCents: planLineCents, amountCents: planLineCents },
665	              ...(extraDiskCents > 0
666	                ? [
667	                    {
668	                      description:
669	                        `${extraDiskLabel(extraDiskGB)} — ${term.label} ` +
670	                        `($${(extraDiskMonthlyCents / 100).toFixed(2)}/mo, permanent: storage can be added but never removed)`,
671	                      qty: 1,
672	                      unitCents: extraDiskCents,
673	                      amountCents: extraDiskCents,
674	                    },
675	                  ]
676	                : []),
677	              ...(backupCents > 0
678	                ? [
679	                    {
680	                      description:
681	                        `${backupTierSpec(backupTier).label} backups (keep ${backupTierSpec(backupTier).keep}) — ${term.label} ` +
682	                        `($${(backupMonthlyCents / 100).toFixed(2)}/mo)`,
683	                      qty: 1,
684	                      unitCents: backupCents,
685	                      amountCents: backupCents,
686	                    },
687	                  ]
688	                : []),
689	            ],
690	          }),
691	        });
692	      }
693	      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
694	        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
695	        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
696	      }
697	      const s = await tx.server.create({
698	        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
699	        // (regenerated at deploy — identical at runtime then; see lib/promo-redemption.ts).
700	        data: {
701	          name: intent.hostname,
702	          hostname: intent.hostname,
703	          userId: user.id,
704	          planId: plan.id,
705	          osTemplateId: os.id,
706	          nodeId,
707	          addons,
708	          // The wizard sells "Daily auto-backups" ("Nightly snapshots to separate
709	          // storage for easy restore") and re-confirms it on the Review step, but
710	          // `addons.dailyBackup` was write-only: the worker declares the key and
711	          // never reads it, and the REAL scheduler (worker/backup-schedule.ts)
712	          // keys off `autoBackup` + `backupIntervalHours`, whose only writer was
713	          // the Backups tab. Nothing bridged the two, so EVERY server in the live
714	          // DB carried `addons.dailyBackup` with `autoBackup: false` and no backup
715	          // job was ever enqueued. A customer would discover the safety net they
716	          // were promised did not exist at the moment they needed it. Bridge it
717	          // here, at the point of sale. A PAID backup tier (PLUS) implies backups
718	          // are on regardless of the free "Daily auto-backups" toggle — you cannot
719	          // sell retention on a schedule that never runs. `backupTier`/`backupKeep`
720	          // are the columns the retention lever (worker/index.ts backupCreate)
721	          // reads; keep null on FREE so it falls back to the tier default.
722	          autoBackup: !!intent.addonBackup || backupTier !== "FREE",
723	          backupIntervalHours:
724	            !!intent.addonBackup || backupTier !== "FREE" ? backupTierSpec(backupTier).intervalHours : null,
725	          backupTier,
726	          backupKeep: backupTier === "FREE" ? null : backupTierSpec(backupTier).keep,
727	          termMonths: term.months,
728	          // THE RATE THIS TERM WAS SOLD AT, recorded at the moment of sale. Every
729	          // later proration prices the plan delta against this number instead of
730	          // whatever promo happens to be running when the customer clicks resize
731	          // (lib/proration.ts) — otherwise the customer chooses the rate for each
732	          // half of a round trip by choosing the date, and pockets the spread.
733	          // `chargeCents` above is literally promoPriceCents(regular, promo), so
734	          // this scalar and the cash collected describe the same transaction.
735	          // A free admin grant recorded as 100: nothing was paid for these months,
736	          // so nothing may ever prorate out of them.
737	          //
738	          // `effectivePromoPercent` — not `promo.discountPercent` — because a
739	          // card-paid order settles the rate it was SOLD at (see OrderPrice), which
740	          // may no longer be the promo running now, AND because a wallet order that
741	          // lost the first-month-free claim paid FULL price (0% off): recording 100
742	          // there would let a later downgrade prorate out a discount nobody was
743	          // charged. Recording today's rate against a price collected under a
744	          // different one is exactly the drift this column exists to prevent.
745	          termPromoPercent: effectivePromoPercent,
746	          // The ANNUAL discount rate in force when this term was sold, frozen here so
747	          // every later proration prices against it and an up-then-down round trip nets
748	          // to zero even if the admin retunes `annual_discount_percent` in between
749	          // (Finding 2). Ignored for non-annual terms by `termDiscountPct`; a free admin
750	          // grant never prorates, so its value is inert. `quote.annualPct` is the very
751	          // rate `regularPlanCents`/`chargeCents` above were priced at.
752	          annualDiscountPct: quote.annualPct,
753	          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
754	          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
755	          // born at its full size, with no separate expansion job.
756	          extraDiskGB,
757	          wantsDedicatedIp: !!intent.dedicatedIp,
758	          isFree: freeRequested,
759	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
760	        } as Prisma.ServerUncheckedCreateInput,
761	      });
762	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
763	      // Anchor the redemption to the created server so the renewal worker can flip
764	      // `renewed` when this customer bills their second term, and stamp the true
765	      // first-term charge. Same tx, so it commits (or rolls back) with the order.
766	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, s.id, debitCents);
767	      return s;
768	    });
769	  } catch (e) {
770	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
771	    throw e;
772	  }
773	
774	  await db.auditLog.create({
775	    data: {
776	      userId: user.id,
777	      action: "server.order",
778	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
779	    },
780	  });
781	  if (!freeRequested) {
782	    try {
783	      await maybeRewardReferral(user.id);
784	    } catch {
785	      /* non-fatal */
786	    }
787	  }
788	  return server.id;
789	}
