44	/**
45	 * Order a managed Nextcloud (NxCloud) instance.
46	 *
47	 * MONEY SAFETY — this mirrors the audited VPS/hosting order discipline:
48	 *   - no spending while impersonating; verified email required;
49	 *   - the wallet is charged the FULL displayed monthly price (NO first-month-free —
50	 *     that promo is shared-hosting only), in the SAME transaction that creates the
51	 *     records, so a rolled-back charge leaves no instance and no invoice;
52	 *   - the amount charged is exactly `plan.priceCents`, which is also what the
53	 *     backing Server renews at (its `serverPlan.priceCents` is seeded equal), so
54	 *     displayed === charged === renewed.
55	 *
56	 * The instance is backed by a real `Server`, created here with a PROVISION job.
57	 * The worker clones/sizes the VM and bakes in the Nextcloud install (worker/nxcloud.ts);
58	 * the instance flips to ACTIVE once it verifies serving.
59	 */
60	export async function orderNxCloud(planId: string, subdomainRaw: string): Promise<NxCloudResult> {
61	  const user = await requireUser();
62	  await assertNotImpersonating();
63	
64	  // Ordering gate. NxCloud is visible product-wide, but provisioning must not open
65	  // until the *.nxcloud.nxeon.cloud wildcard DNS exists (Caddy auto-TLS depends on
66	  // it) and the provisioning path has passed a security review. Until the owner
67	  // flips `nxcloud_ordering_enabled`, refuse before touching the wallet. This is a
68	  // pure gate — it changes no price and no money-flow logic below.
69	  if (!(await getSettingBool("nxcloud_ordering_enabled", false))) {
70	    return { error: "NxCloud isn’t open for orders yet — join the waitlist and we’ll let you know the moment it launches." };
71	  }
72	
73	  const unverified = await emailVerificationError(user);
74	  if (unverified) return { error: unverified };
75	
76	  const subdomain = normalizeSubdomain(subdomainRaw);
77	  if (!subdomain) return { error: "Choose a subdomain for your cloud." };
78	  if (!isValidSubdomainLabel(subdomain)) {
79	    return { error: "Subdomain: 3–32 lowercase letters, digits or hyphens (not a reserved word)." };
80	  }
81	
82	  const plan = await db.nxCloudPlan.findUnique({ where: { id: planId }, include: { serverPlan: true } });
83	  if (!plan || !plan.active) return { error: "That NxCloud plan isn’t available." };
84	  if (!plan.serverPlan) return { error: "This plan isn’t fully configured yet — please contact support." };
85	
86	  // The Nextcloud OS image the VM clones from (seeded by prisma/seed-nxcloud.ts).
87	  const osTemplate = await db.osTemplate.findUnique({ where: { slug: "nextcloud" } });
88	  if (!osTemplate) return { error: "NxCloud isn’t available yet — the Nextcloud image hasn’t been seeded." };
89	
90	  // Subdomain is globally unique across all customers (it's a public hostname).
91	  const taken = await db.nxCloudInstance.findFirst({
92	    where: { subdomain, status: { in: [...LIVE_STATES] } },
93	    select: { id: true, userId: true },
94	  });
95	  if (taken) {
96	    return {
97	      error:
98	        taken.userId === user.id
99	          ? "You already have a cloud with that subdomain."
100	          : "That subdomain is taken — try another.",
101	    };
102	  }
103	
104	  const chargeCents = plan.priceCents;
105	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
106	
107	  const nodeId = await scheduleNode(plan.serverPlan.ramMB);
108	  const zone = (await getSetting("nxcloud_zone", NXCLOUD_DEFAULT_ZONE)).trim() || NXCLOUD_DEFAULT_ZONE;
109	  const fqdn = nxcloudFqdn(subdomain, zone);
110	
111	  let instanceId = "";
112	  try {
113	    await db.$transaction(async (tx) => {
114	      await debitWallet(tx, user.id, chargeCents);
115	      await tx.walletTransaction.create({
116	        data: {
117	          userId: user.id,
118	          amountCents: -chargeCents,
119	          description: `NxCloud: ${plan.name} (${fqdn})`,
120	        },
121	      });
122	      await tx.invoice.create({
123	        data: invoiceCreateData({
124	          userId: user.id,
125	          description: `NxCloud: ${plan.name} (${fqdn})`,
126	          status: "PAID",
127	          period: { start: new Date(), end: addMonths(new Date(), 1) },
128	          lineItems: [
129	            { description: `${plan.name} — managed Nextcloud (${fqdn})`, qty: 1, unitCents: chargeCents, amountCents: chargeCents },
130	          ],
131	        }),
132	      });
133	      // The backing VM. A normal Server — it renews / duns / suspends / monitors
134	      // through the exact same audited machinery as a VPS. VM snapshot backups are
135	      // ON by default (data-loss safety, spec §6); a public IP is requested so the
136	      // instance is reachable by hostname for auto-TLS.
137	      const server = await tx.server.create({
138	        data: {
139	          name: subdomain,
140	          hostname: subdomain,
141	          userId: user.id,
142	          planId: plan.serverPlanId,
143	          osTemplateId: osTemplate.id,
144	          nodeId,
145	          autoBackup: true,
146	          backupIntervalHours: 24,
147	          termMonths: 1,
148	          // Sold at full price — 0% off — so no later proration can claw a discount
149	          // that was never given (see Server.termPromoPercent).
150	          termPromoPercent: 0,
151	          wantsDedicatedIp: true,
152	          isFree: false,
153	          expiresAt: addMonths(new Date(), 1),
154	        },
155	      });
156	      const inst = await tx.nxCloudInstance.create({
157	        data: {
158	          userId: user.id,
159	          planId: plan.id,
160	          serverId: server.id,
161	          subdomain,
162	          status: "PENDING",
163	          adminUser: "admin",
164	          storageQuotaMB: plan.storageGB * 1024,
165	        },
166	      });
167	      instanceId = inst.id;
168	      await tx.job.create({ data: { type: "PROVISION", serverId: server.id } });
169	    });
170	  } catch (e) {
171	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
172	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
173	  }
174	
175	  await db.auditLog
176	    .create({ data: { userId: user.id, action: "nxcloud.order", detail: `${plan.name} · ${fqdn}` } })
177	    .catch(() => {});
178	  revalidatePath("/dashboard/nxcloud");
179	  return { ok: true, instanceId };
180	}
