246	export async function revealNxcloudAdminPassword(instanceId: string): Promise<{ password?: string; error?: string }> {
247	  const user = await requireUser();
248	  await assertNotImpersonating();
249	  const inst = await db.nxCloudInstance.findUnique({
250	    where: { id: instanceId },
251	    select: { userId: true, adminPassEnc: true },
252	  });
253	  if (!inst) return { error: "Not found." };
254	  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
255	  const pw = inst.adminPassEnc ? decryptSecret(inst.adminPassEnc) : null;
256	  if (!pw) return { error: "No password on record yet — your cloud is still being set up." };
257	  return { password: pw };
