261	export async function resetNxcloudAdminPassword(instanceId: string): Promise<NxCloudResult> {
262	  const user = await requireUser();
263	  await assertNotImpersonating();
264	  const inst = await db.nxCloudInstance.findUnique({ where: { id: instanceId }, select: { userId: true, status: true } });
265	  if (!inst) return { error: "Not found." };
266	  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
267	  if (inst.status !== "ACTIVE") return { error: "Wait until your cloud is active, then reset the password." };
268	  await db.nxCloudTask.create({ data: { instanceId, kind: "RESET_ADMIN_PW" } });
