273	/**
274	 * Terminate an instance: destroy the backing VM (enqueue a Server DELETE — the
275	 * audited teardown that stops billing and purges the disk) and remove the
276	 * instance record. Irreversible; the customer's files go with the VM.
277	 */
278	export async function terminateNxcloud(instanceId: string): Promise<NxCloudResult> {
279	  const user = await requireUser();
280	  await assertNotImpersonating();
281	  const inst = await db.nxCloudInstance.findUnique({ where: { id: instanceId }, select: { userId: true, serverId: true } });
282	  if (!inst) return { error: "Not found." };
283	  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
284	  if (inst.serverId) {
285	    await db.job.create({ data: { type: "DELETE", serverId: inst.serverId } });
286	  }
287	  // Drop the wrapper row (tasks cascade). The DELETE job tears the VM down.
288	  await db.nxCloudInstance.delete({ where: { id: instanceId } });
289	  await db.auditLog.create({ data: { userId: user.id, action: "nxcloud.terminate", detail: instanceId } }).catch(() => {});
290	  revalidatePath("/dashboard/nxcloud");
291	  return { ok: true };
292	}
