71	    gameFamily: formData.get("gameFamily"),
72	    name: formData.get("name"),
73	    ramMB: formData.get("ramMB"),
74	    cpuCores: formData.get("cpuCores"),
75	    diskGB: formData.get("diskGB"),
76	    slots: rawSlots === "" ? undefined : rawSlots,
77	    priceCents: formData.get("priceCents"),
