98	    osTemplateId = os.id;
99	  }
100	
101	  const featured = formData.get("featured") === "on";
102	  const active = formData.get("active") === "on";
103	
104	  const data = {
105	    gameFamily: d.gameFamily,
106	    name: d.name.trim(),
107	    ramMB: d.ramMB,
108	    cpuCores: d.cpuCores,
109	    diskGB: d.diskGB,
110	    slots: d.slots ?? null,
