177	/**
178	 * Order a game server from a GamePlan tier. Mirrors the VPS deploy path
179	 * (lib/actions.ts payAndDeploy -> lib/order.ts placeOrder):
180	 * validate the tier, atomically debit the wallet for `gamePlan.priceCents`, then
181	 * create the Server (sized by the tier's base VPS plan, running the game image)
182	 * plus a PROVISION Job in one transaction. Redirects to the new server.
183	 */
184	export async function orderGameServer(gamePlanId: string): Promise<Result> {
185	  // Spend path: this debits the wallet for the tier's flat price. The docblock
186	  // above says it mirrors the VPS deploy path — `payAndDeploy` (lib/actions.ts)
187	  // has carried this guard since it was written and this copy never picked it up.
188	  await assertNotImpersonating();
189	  const user = await requireUser();
190	  // Purchase gate: an unverified address means we cannot reach the person we
191	  // are about to charge. See lib/email-verification.ts.
192	  const unverified = await emailVerificationError(user);
193	  if (unverified) return { error: unverified };
194	
195	  // Feature flag: game servers can be switched off platform-wide.
196	  if (!(await getSettingBool("feature_game_servers", true))) {
197	    return { error: "Game servers aren't available right now." };
198	  }
199	
200	  // Game servers are Server rows too, so they count toward the per-user cap
201	  // (`max_servers_per_user`, default 10; 0 = unlimited).
202	  const cap = await getSettingInt("max_servers_per_user", 10);
203	  if (cap > 0) {
204	    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
205	    if (owned >= cap) {
206	      return { error: `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.` };
207	    }
208	  }
209	
210	  const gp = await db.gamePlan.findUnique({
211	    where: { id: gamePlanId },
212	    include: { basePlan: true },
213	  });
214	  if (!gp || !gp.active) return { error: "That game plan isn't available." };
215	  if (!gp.basePlan?.active) return { error: "Provisioning is temporarily unavailable for this game." };
216	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
217	    return { error: "Unknown game family." };
218	  }
219	
220	  // Resolve the game image: the tier's own OsTemplate, else any active image for
221	  // this game family. A game server can't provision without an image.
222	  let osTemplateId = gp.osTemplateId;
223	  if (osTemplateId) {
224	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
225	    if (!os?.active) osTemplateId = null;
226	  }
227	  if (!osTemplateId) {
228	    const os = await db.osTemplate.findFirst({
229	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
230	      orderBy: { sortOrder: "asc" },
231	    });
232	    if (!os) return { error: "No game image is configured for this game yet." };
233	    osTemplateId = os.id;
234	  }
235	
236	  // Managed first-month-free. A game plan is a flat all-in term price, so the
237	  // credit is ONE month of that rate (firstMonthCreditCents); a single-month plan
238	  // lands at $0. `fullCharge` is the flat price. The credit applies ONLY if the
239	  // atomic claim inside the charge tx succeeds — otherwise (already redeemed by
240	  // this account/IP, or the promo is off) the server is created at FULL price. The
241	  // eligibility pre-check only picks the balance gate so a first-time customer with
242	  // just enough for the discounted price isn't wrongly turned away.
243	  // First-month-free is scoped to Shared Web Hosting only — game plans always
244	  // bill full. firstMonthFreeAppliesTo("GAME") is false, so promoEnabled is false.
245	  const promoEnabled = firstMonthFreeAppliesTo("GAME") && (await firstMonthFreeEnabled());
246	  const campaign = promoCampaignFromCookie(await cookies());
247	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
248	  const fullCharge = gp.priceCents;
249	  const promoCharge = Math.max(0, gp.priceCents - firstMonthCreditCents(gp.priceCents, gp.termMonths));
250	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
251	  const anticipated = eligible ? promoCharge : fullCharge;
252	  if (user.balanceCents < anticipated) {
253	    return { error: "Insufficient balance. Top up your wallet first." };
254	  }
255	
256	  // Oversell guard — the VPS order path enforces this but game orders skipped it,
257	  // letting game servers commit host RAM past capacity. Check the base plan's
258	  // footprint before charging or enqueuing a PROVISION that can't be scheduled.
259	  const capacity = await capacityCheck(gp.basePlanId);
260	  if (!capacity.ok) return { error: capacity.reason ?? "The host is at capacity right now. Please try again shortly." };
261	
262	  const hostname = `${gp.gameFamily}-${rand()}`;
263	
264	  let server;
265	  try {
266	    server = await db.$transaction(async (tx) => {
267	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
268	      let debitCents = fullCharge;
269	      let promoClaimId: string | null = null;
270	      if (promoEnabled) {
271	        const claim = await claimFirstMonthFree(tx, {
272	          userId: user.id,
273	          ipHash,
274	          serviceType: "GAME",
275	          campaign,
276	          chargedCents: promoCharge,
277	        });
278	        if (claim.claimed) {
279	          debitCents = promoCharge;
280	          promoClaimId = claim.id;
281	        }
282	      }
283	      const note = debitCents < fullCharge ? " — First month free" : "";
284	      await debitWallet(tx, user.id, debitCents);
285	      await tx.walletTransaction.create({
286	        data: {
287	          userId: user.id,
288	          amountCents: -debitCents,
289	          description: `Game server: ${gp.name} (${gp.gameFamily})${note}`,
290	        },
291	      });
292	      const s = await tx.server.create({
293	        data: {
294	          name: hostname,
295	          hostname,
296	          userId: user.id,
297	          planId: gp.basePlanId,
298	          gamePlanId: gp.id,
299	          osTemplateId: osTemplateId!,
300	          termMonths: gp.termMonths,
301	          // A game plan is a flat all-in price: `chargeCents` above is
302	          // `gp.priceCents` with no term discount and no seasonal promo applied, and
303	          // renewalCharge (lib/stripe-cards.ts) renews it at that same flat price.
304	          // So this term was sold at 0% off — full price — and any proration must
305	          // price against that, not against whatever promo is running later.
306	          termPromoPercent: 0,
307	          wantsDedicatedIp: false,
308	          expiresAt: addMonths(new Date(), gp.termMonths),
309	        },
310	      });
311	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
312	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, s.id, debitCents);
313	      return s;
314	    });
315	  } catch (e) {
316	    if (e instanceof InsufficientBalanceError) {
317	      return { error: "Insufficient balance. Top up your wallet first." };
318	    }
319	    throw e;
320	  }
321	
322	  await db.auditLog.create({
323	    data: {
324	      userId: user.id,
325	      action: "gameserver.order",
326	      detail: `${server.id} game=${gp.gameFamily} tier=${gp.name}`,
327	    },
328	  });
329	  redirect(`/dashboard/servers/${server.id}`);
330	}
