23	/**
24	 * Recurring billing for the add-on products: business email subscriptions and
25	 * block-storage volumes. Until this existed only the *first* period was charged
26	 * at order time and nothing ever renewed — every one of these products was
27	 * silently free after month one.
28	 *
29	 * Policy (mirrors worker/billing.ts so the whole account behaves the same):
30	 *   T-3d   warn the owner if the renewal would fail (no funds / auto-renew off)
31	 *   T+0    charge the wallet, push `expiresAt` forward one term
32	 *   T+0..G still unpaid: keep it running, nag once per dedupe window
33	 *   T+G    enforce — email: status SUSPENDED (mailboxes kept)
34	 *                    volume: DETACHED + VOLUME_DETACH job (data kept)
35	 * Nothing here ever deletes customer data.
36	 *
37	 * The orchestrator (worker/index.ts) calls `productRenewalSweep()` on a timer.
38	 * Every step is individually try/caught so one poisoned row can never abort the
39	 * sweep, and every mutation is a conditional compare-and-swap so a re-run — or
40	 * two workers racing — can never double-charge.
41	 */
42	
43	const LOG = "[product-billing]";
44	
45	/** Thrown inside a renewal transaction when another sweep already handled the row. */
46	class AlreadyHandledError extends Error {
47	  constructor(what: string) {
48	    super(`already handled: ${what}`);
49	    this.name = "AlreadyHandledError";
50	  }
51	}
52	
53	/** Run a sweep phase, swallowing (but logging) any failure so the rest proceeds. */
54	async function phase(name: string, fn: () => Promise<void>): Promise<void> {
55	  try {
56	    await fn();
57	  } catch (e) {
58	    console.error(`${LOG} phase "${name}" failed`, e);
59	  }
60	}
61	
62	/** Run a per-row step; a bad row is logged and skipped, never fatal. */
63	async function step(what: string, fn: () => Promise<void>): Promise<void> {
64	  try {
65	    await fn();
66	  } catch (e) {
67	    console.error(`${LOG} ${what} failed`, e);
68	  }
69	}
