71	/** Best-effort notification (a notify failure must never roll back a charge). */
72	async function notify(userId: string, title: string, body?: string, href?: string) {
73	  try {
74	    await db.notification.create({ data: { userId, title, body, href } });
75	  } catch (e) {
76	    console.error(`${LOG} notify failed`, e);
77	  }
78	}
