80	/**
81	 * Send a notification at most once per dedupe window, keyed on the entity label
82	 * plus a stable marker phrase in the title (same technique as worker/billing.ts).
83	 */
84	async function notifyOnce(
85	  now: Date,
86	  userId: string,
87	  label: string,
88	  marker: string,
89	  title: string,
90	  body: string,
91	  href: string
92	) {
93	  const already = await db.notification.findFirst({
94	    where: {
95	      userId,
96	      createdAt: { gt: dedupeSince(now) },
97	      AND: [{ title: { contains: label } }, { title: { contains: marker } }],
98	    },
99	    select: { id: true },
100	  });
101	  if (already) return;
102	  await notify(userId, title, body, href);
103	}
