111	/** Heads-up for subscriptions expiring soon whose renewal would fail today. */
112	async function emailUpcomingWarnings(now: Date) {
113	  const soon = new Date(now.getTime() + PRODUCT_WARN_DAYS * 86400_000);
114	  const upcoming = await db.emailSubscription.findMany({
115	    where: { status: "ACTIVE", expiresAt: { gt: now, lt: soon } },
116	    include: { emailPlan: true, user: true },
117	  });
118	
119	  for (const sub of upcoming) {
120	    await step(`email warn ${sub.id}`, async () => {
121	      const priceCents = emailRenewalCents(sub.emailPlan);
122	      if (!needsUpcomingWarning({ autoRenew: sub.autoRenew, balanceCents: sub.user.balanceCents, priceCents })) {
123	        return;
124	      }
125	      await notifyOnce(
126	        now,
127	        sub.userId,
128	        sub.domainName,
129	        "email renews soon",
130	        `${sub.domainName} email renews soon — action needed`,
131	        sub.autoRenew
132	          ? `Renewal is ${money(priceCents)} but your balance is ${money(sub.user.balanceCents)}. Top up before ${ymd(sub.expiresAt!)} to keep your mailboxes delivering.`
133	          : `Auto-renew is off. Renew manually before ${ymd(sub.expiresAt!)} to avoid suspension.`,
134	        EMAIL_HREF
135	      );
136	    });
137	  }
