140	/**
141	 * Charge + extend one subscription atomically.
142	 *
143	 * The compare-and-swap on `expiresAt` is the double-charge guard: the update
144	 * only matches while the row still carries the *old* expiry we based the
145	 * decision on, so a concurrent (or repeated) sweep matches zero rows, throws,
146	 * and rolls the whole transaction — wallet debit included — back.
147	 * Returns true when this call is the one that actually renewed.
148	 */
149	async function chargeEmailRenewal(
150	  sub: { id: string; userId: string; domainName: string; expiresAt: Date | null },
151	  planName: string,
152	  priceCents: number,
153	  newExpiry: Date
154	): Promise<boolean> {
155	  try {
156	    await db.$transaction(async (tx) => {
157	      const advanced = await tx.emailSubscription.updateMany({
158	        where: { id: sub.id, status: "ACTIVE", expiresAt: sub.expiresAt },
159	        data: { expiresAt: newExpiry },
160	      });
161	      if (advanced.count === 0) throw new AlreadyHandledError(`email ${sub.id}`);
162	
163	      if (priceCents > 0) {
164	        await debitWallet(tx, sub.userId, priceCents);
165	        await tx.walletTransaction.create({
166	          data: {
167	            userId: sub.userId,
168	            amountCents: -priceCents,
169	            description: `Business Email renewal: ${planName} for ${sub.domainName}`,
170	          },
171	        });
172	        // PAID invoice, inside the CAS-guarded tx — a repeated sweep matches zero
173	        // rows, throws AlreadyHandledError, and rolls this invoice back too.
174	        await tx.invoice.create({
175	          data: invoiceCreateData({
176	            userId: sub.userId,
177	            description: `Business Email renewal: ${planName} for ${sub.domainName}`,
178	            status: "PAID",
179	            period: { start: sub.expiresAt, end: newExpiry },
180	            lineItems: [
181	              { description: `${planName} — ${sub.domainName}`, qty: 1, unitCents: priceCents, amountCents: priceCents },
182	            ],
183	          }),
184	        });
185	      }
186	      await tx.auditLog.create({
187	        data: {
188	          userId: sub.userId,
189	          action: "billing.renewed",
190	          detail: `email ${sub.id} ${sub.domainName} ${money(priceCents)} -> ${ymd(newExpiry)}`,
191	        },
192	      });
193	      // First-month-free conversion: this is the SECOND term. Flip the redemption
194	      // anchored to this subscription to renewed (idempotent, same tx as the money).
195	      await markPromoRenewed(tx, sub.id);
196	    });
197	    return true;
198	  } catch (e) {
199	    if (e instanceof AlreadyHandledError) {
200	      console.log(`${LOG} email ${sub.id} already renewed by another pass — skipping`);
201	      return false;
202	    }
203	    if (e instanceof InsufficientBalanceError) {
204	      // Balance was spent between the read and the debit; the warn/grace path
205	      // picks it up on the next sweep.
206	      console.log(`${LOG} email ${sub.id} lost the race for funds — retrying next sweep`);
207	      return false;
208	    }
209	    throw e;
210	  }
211	}
