240	/** Renew / warn / suspend every ACTIVE subscription that is past its expiry. */
241	async function emailDueSweep(now: Date) {
242	  const due = await db.emailSubscription.findMany({
243	    where: { status: "ACTIVE", expiresAt: { not: null, lt: now } },
244	    include: { emailPlan: true, user: true },
245	  });
246	
247	  for (const sub of due) {
248	    await step(`email renewal ${sub.id}`, async () => {
249	      if (!sub.expiresAt) return;
250	      const priceCents = emailRenewalCents(sub.emailPlan);
251	      const action = renewalDecision({
252	        expiresAt: sub.expiresAt,
253	        now,
254	        autoRenew: sub.autoRenew,
255	        balanceCents: sub.user.balanceCents,
256	        priceCents,
257	      });
258	
259	      if (action === "renew") {
260	        const newExpiry = nextExpiry(sub.expiresAt, now, emailRenewalMonths(sub.emailPlan));
261	        const renewed = await chargeEmailRenewal(sub, sub.emailPlan.name, priceCents, newExpiry);
262	        if (!renewed) return;
263	        await notify(
264	          sub.userId,
265	          `${sub.domainName} email renewed`,
266	          `Charged ${money(priceCents)} for ${sub.emailPlan.name}. Next renewal ${ymd(newExpiry)}.`,
267	          EMAIL_HREF
268	        );
269	        console.log(`${LOG} renewed email ${sub.domainName} until ${newExpiry.toISOString()}`);
270	        return;
271	      }
272	
273	      if (action === "enforce") {
274	        await suspendEmail(sub, priceCents);
275	        return;
276	      }
277	
278	      // Still inside the grace window — keep it delivering, nag once.
279	      await notifyOnce(
280	        now,
281	        sub.userId,
282	        sub.domainName,
283	        "email renewal failed",
284	        `${sub.domainName} email renewal failed — top up to keep it active`,
285	        sub.autoRenew
286	          ? `We couldn't charge ${money(priceCents)} (balance ${money(sub.user.balanceCents)}). Mail keeps flowing until ${ymd(graceEndsAt(sub.expiresAt, PRODUCT_GRACE_DAYS))}, then the subscription is suspended. Your mailboxes are not deleted.`
287	          : `Auto-renew is off and this subscription expired. Renew before ${ymd(graceEndsAt(sub.expiresAt, PRODUCT_GRACE_DAYS))} to avoid suspension. Your mailboxes are not deleted.`,
288	        EMAIL_HREF
289	      );
290	    });
291	  }
292	}
