421	/**
422	 * Charge + extend one volume atomically. Same compare-and-swap on `expiresAt`
423	 * as the email path, so re-running the sweep can never bill a second month.
424	 */
425	async function chargeVolumeRenewal(
426	  volume: { id: string; userId: string; name: string; sizeGB: number; expiresAt: Date | null; status: string },
427	  priceCents: number,
428	  newExpiry: Date
429	): Promise<boolean> {
430	  try {
431	    await db.$transaction(async (tx) => {
432	      const advanced = await tx.volume.updateMany({
433	        where: { id: volume.id, status: { in: BILLABLE_VOLUME_STATUSES }, expiresAt: volume.expiresAt },
434	        data: { expiresAt: newExpiry },
435	      });
436	      if (advanced.count === 0) throw new AlreadyHandledError(`volume ${volume.id}`);
437	
438	      if (priceCents > 0) {
439	        await debitWallet(tx, volume.userId, priceCents);
440	        await tx.walletTransaction.create({
441	          data: {
442	            userId: volume.userId,
443	            amountCents: -priceCents,
444	            description: `Block storage renewal: ${volume.name} (${volume.sizeGB} GB)`,
445	          },
446	        });
447	        // PAID invoice, inside the CAS-guarded tx — a repeated sweep rolls back.
448	        await tx.invoice.create({
449	          data: invoiceCreateData({
450	            userId: volume.userId,
451	            description: `Block storage renewal: ${volume.name} (${volume.sizeGB} GB)`,
452	            status: "PAID",
453	            period: { start: volume.expiresAt, end: newExpiry },
454	            lineItems: [
455	              { description: `Block storage — ${volume.name} (${volume.sizeGB} GB)`, qty: 1, unitCents: priceCents, amountCents: priceCents },
456	            ],
457	          }),
458	        });
459	      }
460	      await tx.auditLog.create({
461	        data: {
462	          userId: volume.userId,
463	          action: "billing.renewed",
464	          detail: `volume ${volume.id} ${volume.name} ${money(priceCents)} -> ${ymd(newExpiry)}`,
465	        },
466	      });
467	    });
468	    return true;
469	  } catch (e) {
470	    if (e instanceof AlreadyHandledError) {
471	      console.log(`${LOG} volume ${volume.id} already renewed by another pass — skipping`);
472	      return false;
473	    }
474	    if (e instanceof InsufficientBalanceError) {
475	      console.log(`${LOG} volume ${volume.id} lost the race for funds — retrying next sweep`);
476	      return false;
477	    }
478	    throw e;
479	  }
480	}
