482	/**
483	 * Enforcement for an unpaid volume past grace: detach only, never destroy.
484	 * An ATTACHED volume is flipped to DETACHED and a VOLUME_DETACH job is queued
485	 * (both in one transaction, so we never mark it detached without doing it).
486	 * The underlying disk — and every byte on it — is left intact.
487	 */
488	async function detachUnpaidVolume(
489	  volume: {
490	    id: string;
491	    userId: string;
492	    name: string;
493	    serverId: string | null;
494	    status: string;
495	    expiresAt: Date | null;
496	  },
497	  priceCents: number,
498	  now: Date
499	) {
500	  if (volume.status !== "ATTACHED") {
501	    // Nothing to detach (PENDING / already DETACHED) — just keep nagging.
502	    await notifyOnce(
503	      now,
504	      volume.userId,
505	      volume.name,
506	      "volume unpaid",
507	      `Volume "${volume.name}" is unpaid`,
508	      `This volume is overdue by ${money(priceCents)}/mo. Your data is retained, but the volume may be removed if it stays unpaid past ${ymd(reclaimAt(volume.expiresAt!))}. Top up to keep it.`,
509	      VOLUME_HREF
510	    );
511	    return;
512	  }
513	
514	  // Respect the one-in-flight-job guard so we don't collide with a user or
515	  // worker operation already running on that server; retry on the next sweep.
516	  if (volume.serverId) {
517	    const busy = await db.job.count({
518	      where: { serverId: volume.serverId, status: { in: ["QUEUED", "RUNNING"] } },
519	    });
520	    if (busy > 0) return;
521	  }
522	
523	  try {
524	    await db.$transaction(async (tx) => {
525	      const flipped = await tx.volume.updateMany({
526	        where: { id: volume.id, status: "ATTACHED" },
527	        data: { status: "DETACHED" },
528	      });
529	      if (flipped.count === 0) throw new AlreadyHandledError(`volume ${volume.id}`);
530	      await tx.job.create({
531	        data: { type: "VOLUME_DETACH", serverId: volume.serverId, payload: { volumeId: volume.id } },
532	      });
533	      await tx.auditLog.create({
534	        data: {
535	          userId: volume.userId,
536	          action: "billing.volume_detached_unpaid",
537	          detail: `volume ${volume.id} ${volume.name}`,
538	        },
539	      });
540	    });
541	  } catch (e) {
542	    if (e instanceof AlreadyHandledError) return;
543	    throw e;
544	  }
545	
546	  await notify(
547	    volume.userId,
548	    `Volume "${volume.name}" detached — payment overdue`,
549	    `We couldn't collect ${money(priceCents)} for this volume, so it was detached from your server. Nothing was deleted: all data on the volume is retained and re-attaches exactly as it was once you top up and renew. If it stays unpaid past ${ymd(reclaimAt(volume.expiresAt!))} the volume may be removed.`,
550	    VOLUME_HREF
551	  );
552	  console.log(`${LOG} detached unpaid volume ${volume.id} (${volume.name})`);
553	}
