555	/** Renew / warn / detach every billable volume that is past its expiry. */
556	async function volumeDueSweep(now: Date) {
557	  const due = await db.volume.findMany({
558	    where: { status: { in: BILLABLE_VOLUME_STATUSES }, expiresAt: { not: null, lt: now } },
559	    include: { user: true },
560	  });
561	
562	  for (const volume of due) {
