569	        autoRenew: true, // volumes have no opt-out; they renew until deleted
570	        balanceCents: volume.user.balanceCents,
571	        priceCents,
572	      });
573	
574	      if (action === "renew") {
575	        const newExpiry = nextExpiry(volume.expiresAt, now, VOLUME_TERM_MONTHS);
576	        const renewed = await chargeVolumeRenewal(volume, priceCents, newExpiry);
577	        if (!renewed) return;
