579	          volume.userId,
580	          `Volume "${volume.name}" renewed`,
581	          `Charged ${money(priceCents)} for ${volume.sizeGB} GB. Next renewal ${ymd(newExpiry)}.`,
582	          VOLUME_HREF
583	        );
584	        console.log(`${LOG} renewed volume ${volume.id} until ${newExpiry.toISOString()}`);
585	        return;
586	      }
587	
588	      if (action === "enforce") {
589	        await detachUnpaidVolume(volume, priceCents, now);
590	        return;
591	      }
592	
593	      // Inside grace — the volume stays attached and usable; nag once.
594	      await notifyOnce(
595	        now,
596	        volume.userId,
597	        volume.name,
598	        "volume renewal failed",
599	        `Volume "${volume.name}" renewal failed — top up to keep it attached`,
600	        `We couldn't charge ${money(priceCents)} (balance ${money(volume.user.balanceCents)}). The volume stays attached until ${ymd(graceEndsAt(volume.expiresAt, PRODUCT_GRACE_DAYS))}, then it is detached from your server. Your data is never deleted automatically.`,
601	        VOLUME_HREF
602	      );
603	    });
604	  }
