609	/**
610	 * Renewal sweep for the add-on products. Safe to call as often as you like:
611	 * each phase only acts on rows whose `expiresAt` is genuinely in the past, and
612	 * every charge advances `expiresAt` in the same transaction, so repeated runs
613	 * are no-ops rather than repeat charges.
614	 *
615	 * Wire into the worker loop next to `billingSweep()` (see worker/index.ts).
616	 */
617	export async function productRenewalSweep(): Promise<void> {
618	  const now = new Date();
619	  await phase("email upcoming warnings", () => emailUpcomingWarnings(now));
620	  await phase("email renewals", () => emailDueSweep(now));
621	  await phase("volume upcoming warnings", () => volumeUpcomingWarnings(now));
622	  await phase("volume renewals", () => volumeDueSweep(now));
623	  await phase("hosting renewals", () => hostingDueSweep(now));
624	}
