186	export async function orderGameServer(gamePlanId: string): Promise<Result> {
187	  // Spend path: this debits the wallet for the tier's flat price. The docblock
188	  // above says it mirrors the VPS deploy path — `payAndDeploy` (lib/actions.ts)
189	  // has carried this guard since it was written and this copy never picked it up.
190	  await assertNotImpersonating();
191	  const user = await requireUser();
192	  // Purchase gate: an unverified address means we cannot reach the person we
193	  // are about to charge. See lib/email-verification.ts.
194	  const unverified = await emailVerificationError(user);
195	  if (unverified) return { error: unverified };
196	
197	  // Feature flag: game servers can be switched off platform-wide.
198	  if (!(await getSettingBool("feature_game_servers", true))) {
199	    return { error: "Game servers aren't available right now." };
200	  }
201	
202	  // Game servers are Server rows too, so they count toward the per-user cap
203	  // (`max_servers_per_user`, default 10; 0 = unlimited).
204	  const cap = await getSettingInt("max_servers_per_user", 10);
205	  if (cap > 0) {
206	    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
207	    if (owned >= cap) {
208	      return { error: `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.` };
209	    }
210	  }
211	
212	  const gp = await db.gamePlan.findUnique({
213	    where: { id: gamePlanId },
214	    include: { basePlan: true },
215	  });
216	  if (!gp || !gp.active) return { error: "That game plan isn't available." };
217	  if (!gp.basePlan?.active) return { error: "Provisioning is temporarily unavailable for this game." };
218	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
219	    return { error: "Unknown game family." };
220	  }
221	
222	  // Resolve the game image: the tier's own OsTemplate, else any active image for
223	  // this game family. A game server can't provision without an image.
224	  let osTemplateId = gp.osTemplateId;
225	  if (osTemplateId) {
226	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
227	    if (!os?.active) osTemplateId = null;
228	  }
229	  if (!osTemplateId) {
230	    const os = await db.osTemplate.findFirst({
231	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
232	      orderBy: { sortOrder: "asc" },
233	    });
234	    if (!os) return { error: "No game image is configured for this game yet." };
235	    osTemplateId = os.id;
236	  }
237	
238	  // Managed first-month-free. A game plan is a flat all-in term price, so the
239	  // credit is ONE month of that rate (firstMonthCreditCents); a single-month plan
240	  // lands at $0. `fullCharge` is the flat price. The credit applies ONLY if the
241	  // atomic claim inside the charge tx succeeds — otherwise (already redeemed by
242	  // this account/IP, or the promo is off) the server is created at FULL price. The
243	  // eligibility pre-check only picks the balance gate so a first-time customer with
244	  // just enough for the discounted price isn't wrongly turned away.
245	  // First-month-free is scoped to Shared Web Hosting only — game plans always
246	  // bill full. firstMonthFreeAppliesTo("GAME") is false, so promoEnabled is false.
247	  const promoEnabled = firstMonthFreeAppliesTo("GAME") && (await firstMonthFreeEnabled());
248	  const campaign = promoCampaignFromCookie(await cookies());
249	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
250	  const fullCharge = gp.priceCents;
251	  const promoCharge = Math.max(0, gp.priceCents - firstMonthCreditCents(gp.priceCents, gp.termMonths));
252	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
253	  const anticipated = eligible ? promoCharge : fullCharge;
254	  if (user.balanceCents < anticipated) {
255	    return { error: "Insufficient balance. Top up your wallet first." };
256	  }
257	
258	  // Oversell guard — the VPS order path enforces this but game orders skipped it,
259	  // letting game servers commit host RAM past capacity. Check the base plan's
260	  // footprint before charging or enqueuing a PROVISION that can't be scheduled.
261	  const capacity = await capacityCheck(gp.basePlanId);
262	  if (!capacity.ok) return { error: capacity.reason ?? "The host is at capacity right now. Please try again shortly." };
263	
264	  const hostname = `${gp.gameFamily}-${rand()}`;
265	
266	  let server;
267	  try {
268	    server = await db.$transaction(async (tx) => {
269	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
270	      let debitCents = fullCharge;
271	      let promoClaimId: string | null = null;
272	      if (promoEnabled) {
273	        const claim = await claimFirstMonthFree(tx, {
274	          userId: user.id,
275	          ipHash,
276	          serviceType: "GAME",
277	          campaign,
278	          chargedCents: promoCharge,
279	        });
280	        if (claim.claimed) {
281	          debitCents = promoCharge;
282	          promoClaimId = claim.id;
283	        }
284	      }
285	      const note = debitCents < fullCharge ? " — First month free" : "";
286	      await debitWallet(tx, user.id, debitCents);
287	      await tx.walletTransaction.create({
288	        data: {
289	          userId: user.id,
290	          amountCents: -debitCents,
291	          description: `Game server: ${gp.name} (${gp.gameFamily})${note}`,
292	        },
293	      });
294	      const s = await tx.server.create({
295	        data: {
296	          name: hostname,
297	          hostname,
298	          userId: user.id,
299	          planId: gp.basePlanId,
300	          gamePlanId: gp.id,
301	          osTemplateId: osTemplateId!,
302	          termMonths: gp.termMonths,
303	          // A game plan is a flat all-in price: `chargeCents` above is
304	          // `gp.priceCents` with no term discount and no seasonal promo applied, and
305	          // renewalCharge (lib/stripe-cards.ts) renews it at that same flat price.
306	          // So this term was sold at 0% off — full price — and any proration must
307	          // price against that, not against whatever promo is running later.
308	          termPromoPercent: 0,
309	          wantsDedicatedIp: false,
310	          expiresAt: addMonths(new Date(), gp.termMonths),
311	        },
312	      });
313	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
314	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, s.id, debitCents);

