export function GameDeploy({
  games,
  tiers,
  balanceCents,
  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
}: {
  games: GameMeta[];
  tiers: Tier[];
  balanceCents: number;
  /** Live admin annual discount (%), so the Annual card shows the REAL price/savings. */
  annualDiscountPct?: number;
}) {
  const firstGame = games[0]?.family ?? "";
  const [game, setGame] = useState(firstGame);
  const [selected, setSelected] = useState<string | null>(null);
  const [termMonths, setTermMonths] = useState(1);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const gameTiers = useMemo(
    () => tiers.filter((t) => t.gameFamily === game).sort((a, b) => a.priceCents - b.priceCents),
    [tiers, game],
  );

  const chosen = gameTiers.find((t) => t.id === selected) ?? null;
  // What this order costs at the chosen term — the SAME formula the server charges
  // (termPriceCents), so what's shown here is what's charged and renewed.
  const chargeCents = chosen ? termPriceCents(chosen.priceCents, termMonths, annualDiscountPct) : 0;
  const insufficient = chosen ? balanceCents < chargeCents : false;

  function deploy() {
    if (!chosen) return;
    setError(null);
    start(async () => {
      const res = await orderGameServer(chosen.id, termMonths);
      // On success orderGameServer redirects; only errors return here.
      if (res?.error) setError(res.error);
    });
  }

{/* Step 3 — billing term */}
{chosen && (
  <div>
    <p className="label mb-2">3 · Billing term</p>
    <div className="grid gap-3 sm:grid-cols-2">
      {PRODUCT_TERMS.map((t) => {
        const total = termPriceCents(chosen.priceCents, t.months, annualDiscountPct);
        const perMo = Math.round(total / t.months);
        const savings = chosen.priceCents * t.months - total;
        const disc = t.months === ANNUAL_TERM_MONTHS ? annualDiscountPct : t.discountPct;
        const on = termMonths === t.months;
        return (
          <button
            key={t.months}
            onClick={() => setTermMonths(t.months)}
            className={`card relative text-left transition ${on ? "border-brand-400 ring-1 ring-brand-400/40" : "card-hover"}`}
          >
            {disc > 0 && (
              <span className="absolute right-3 top-3 rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
                −{disc}%
              </span>
            )}
            <p className="text-sm font-semibold text-white">{t.label}</p>
            <p className="mt-1 text-lg font-bold text-white">{money(perMo)}<span className="text-xs font-normal text-slate-400">/mo</span></p>
            <p className="mt-0.5 text-[11px] text-slate-500">
              {money(total)} billed {t.months === 1 ? "monthly" : `every ${t.short}`}
            </p>
            {savings > 0 && (
              <p className="mt-1 text-[11px] font-medium text-emerald-300">
                {money(total)}/yr · save {money(savings)} vs monthly
              </p>
            )}
          </button>
        );
      })}
    </div>
  </div>
)}

{/* Step 4 — deploy */}
{chosen && (
  <div className="card flex flex-wrap items-center justify-between gap-4">
    <div>
      <p className="text-sm text-slate-400">
        Deploying <span className="font-medium text-white">{chosen.name}</span>. You&apos;ll be charged{" "}
        <span className="font-medium text-white">{money(chargeCents)}</span> from your wallet
        (balance {money(balanceCents)}).
      </p>

